// The book: every kept law as a term, by the kept data's own examples, and the slice's derived laws. The book is
// sourced evidence, never the limit of what the language states: laws are generated by carriers (one family for every
// conserved quantity, and for every matter an intent names), by couplings between them, by the binder and by the
// reaction family, and the book's laws are the instances they are checked against.

import type { Law } from '../substrate/law';
import { CHEMISTRY } from './chemistry';
import { ELECTRICAL } from './electrical';
import { FLUIDS } from './fluids';
import { INFORMATION } from './information';
import { MACHINE_ELEMENTS } from './machine-elements';
import { MAGNETISM } from './magnetism';
import { MATERIALS } from './materials';
import { MECHANICS } from './mechanics';
import { OPTICS } from './optics';
import { SLICE } from './slice';
import { STRUCTURES } from './structures';
import { THERMAL } from './thermal';
import { UNIVERSAL } from './universal';

export * from './slice';
export { UNIVERSAL } from './universal';
export { CONST, est } from './constants';

/** The kept book as terms, by area. */
export const KEPT: Record<string, Law[]> = { mechanics: MECHANICS, structures: STRUCTURES, materials: MATERIALS, 'machine elements': MACHINE_ELEMENTS, electrical: ELECTRICAL, thermal: THERMAL, fluids: FLUIDS, magnetism: MAGNETISM, information: INFORMATION, chemistry: CHEMISTRY, optics: OPTICS };

/** The book: the kept laws, the slice's derived ones, and the universal laws everything else is a chain of. */
export const BOOK: Law[] = [...Object.values(KEPT).flat(), ...SLICE, ...UNIVERSAL];

const byId = new Map(BOOK.map((l) => [l.id, l]));
for (const l of BOOK) if (BOOK.filter((x) => x.id === l.id).length > 1) throw new Error(`the book holds ${l.id} twice`);
export const lawById = (id: string): Law => { const l = byId.get(id); if (!l) throw new Error(`no law ${id} in the book`); return l; };
const byHash = new Map(BOOK.map((l) => [l.hash, l]));
/** A kept law by its identity, when a record cites it: the way a derivation names the law it rests on. */
export const lawByHash = (hash: string): Law | undefined => byHash.get(hash);

export const WEIGHT = lawById('weight');
export const BENDING_STRESS = lawById('stress.bending');
export const BAR_WAVE_SPEED = lawById('sound.speed');
